class Solution {
    unordered_map<int, vector<int>> idx;
    mt19937 gen;
public:
    Solution(vector<int>& nums) : gen(random_device{}()) {
        for (int i = 0; i < (int)nums.size(); i++) {
            idx[nums[i]].push_back(i);
        }
    }

    int pick(int target) {
        auto& v = idx[target];
        uniform_int_distribution<int> dist(0, (int)v.size() - 1);
        return v[dist(gen)];
    }
};
